def balancedParenthesesAndSum(expression):
    stack = []
    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return -1
            stack.pop()
    if stack:
        return -1
    return sum(int(digit) for digit in expression if digit.isdigit())

