def replace_missing_values(data: List[List[Optional[float]]]) -> List[List[float]]:
    # Calculate the mean of each column
    means = []
    for col in zip(*data):
        # Filter out None values
        non_none_values = [x for x in col if x is not None]
        if non_none_values:
            means.append(statistics.mean(non_none_values))
        else:
            means.append(0)

    # Replace None values with the calculated means
    cleaned_data = []
    for row in data:
        cleaned_row = []
        for i, val in enumerate(row):
            if val is None:
                cleaned_row.append(means[i])
            else:
                cleaned_row.append(val)
        cleaned_data.append(cleaned_row)

    return cleaned_data

