def unique_sorted_words(inputfile: str, outputfile: str) -> bool:
    try:
        with open(inputfile, 'r') as f_in, open(outputfile, 'w') as f_out:
            # 读取文件，分割句子，转换为小写，存储为集合
            unique_words = set()
            for line in f_in:
                words = line.split()
                for word in words:
                    unique_words.add(word.lower())
            # 排序并写入输出文件
            for word in sorted(unique_words):
                f_out.write(word + '\n')
        return True
    except Exception as e:
        print(f"Error: {e}")
        return False

