import tokenize
import token
import io
import os

def transform_integers_to_hex(file_path: str) -> str:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File {file_path} not found")

    with open(file_path, 'r') as f:
        source_code = f.read()

    tokens = tokenize.generate_tokens(io.StringIO(source_code).readline)
    modified_tokens = []

    for toknum, tokval, _, _, _ in tokens:
        if toknum == token.NUMBER:
            if tokval.startswith('-'):
                modified_tokens.append(tokenize.Token(token.NUMBER, '-0x' + hex(int(tokval))[2:], start=(0, 0)))
            else:
                modified_tokens.append(tokenize.Token(token.NUMBER, '0x' + hex(int(tokval))[2:], start=(0, 0)))
        else:
            modified_tokens.append(tokenize.Token(toknum, tokval, start=(0, 0)))

    modified_source_code = tokenize.untokenize(modified_tokens)

    return modified_source_code

# Test cases
test_cases = [
    ('example.py', 'def compute():\n    a = 10\n    b = 255\n    c = -42\n    print(a + b + c)'),
    ('example.py', 'def compute():\n    a = 0xa\n    b = 0xff\n    c = -0x2a\n    print(a + b + c)')
