def minSessions(tasks, sessionTime):
    tasks.sort()
    left, right = 1, len(tasks)
    while left < right:
        mid = (left + right) // 2
        if sum(tasks[:mid]) <= sessionTime:
            right = mid
        else:
            left = mid + 1
    return left

